/// <summary>
/// Post the sales order invoice
/// </summary>
/// <param name = "_salesId">SalesId reference</param>
/// <returns>SalesFormLetter</returns>
public SalesFormLetter postInvoice(SalesId  _salesId)
{
    SalesFormLetter salesFormLetter;
    SalesLine       salesLine;
    CustPackingSlipJour custPackingSlipJour;
    TmpFrmVirtual   tmpFrmVirtual;
    List packingSlipList = new List(Types::Record);

    while select custPackingSlipJour where custPackingSlipJour.SalesId == _salesId
    {
        tmpFrmVirtual.TableNum = custPackingSlipJour.TableId;
        tmpFrmVirtual.RecordNo = custPackingSlipJour.RecId;
        tmpFrmVirtual.insert();
        packingSlipList.addEnd(tmpFrmVirtual);
    }
    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);

    salesFormLetter.salesTable(SalesTable::find(_salesId));
    salesFormLetter.transDate(systemDateGet());
    salesFormLetter.specQty(SalesUpdate::PackingSlip);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.chooseLines(true);
    salesFormLetter.selectFromJournal(packingSlipList.pack());
    salesFormLetter.run();

    return SalesFormLetter;
}

/// <summary>
/// Calculate query based on shipment Id
/// </summary>
/// <param name = "_shipmentId">Shipment Id reference</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(WMSShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadLines  metLines;
    RefRecId                salesLineRecId;
    Query                   qry = new Query(QueryStr(SalesUpdate));
    QueryBuildDataSource    queryBuildDataSource = qry.dataSourceTable(tableNum(SalesLine));
    QueryBuildRange         queryBuildRange;
    SalesLine               salesLine;

    while select metLines
            where metLines.ShipmentId == _shipmentId
        join RecId from salesLine
            where salesLine.SalesId == metLines.ordernum &&
                salesLine.LineNum == metLines.lineNum
    {
        salesLineRecId = salesLine.RecId;
        queryBuildRange = queryBuildDataSource.addRange(fieldnum(SalesLine, RecId));
        queryBuildRange.value(SysQuery::value(salesLineRecId));
    }
    return new sysQueryRun(qry);
}
